html:
{#- Lab Report for one Diagnostic Test, in the same house style as the other
    HMIS prints (hospital letter head, title bar, boxed sections, signatures).
    Anything not Reported prints with a PROVISIONAL band: only a verified
    report should leave the lab. -#}
{%- set signature_label = frappe.db.get_single_value("Lab Settings", "signature_label") -%}
{%- set report_footer = frappe.db.get_single_value("Lab Settings", "report_footer") -%}
{%- set visit = frappe.db.get_value("Patient Visit", doc.patient_visit, ["uhin_id", "age", "dob", "registration_category"], as_dict=1) if doc.patient_visit else None -%}
{%- set doctor = frappe.db.get_value("Doctor Consultation", doc.doctor_consultation, "doctor") if doc.doctor_consultation else None -%}
{%- set dept = frappe.db.get_value("Lab Test Template", doc.lab_test_template, "department") if doc.lab_test_template else None -%}
{%- set lh_content = frappe.db.get_value("Letter Head", "Landour Community Hospital", "content") -%}
{#- Age: the test's own value, else the visit's, else worked out from date of birth, so it isn't printed blank. -#}
{%- set dob = visit.dob if visit and visit.dob else None -%}
{%- set age = doc.age or (visit.age if visit else None) or ((frappe.utils.date_diff(frappe.utils.nowdate(), dob) // 365) ~ " yrs" if dob else None) -%}
{%- macro user_name(u) -%}{{ frappe.db.get_value("User", u, "full_name") or u }}{%- endmacro -%}
{%- macro dt(v) -%}{{ frappe.utils.format_datetime(v, "dd MMM yyyy, hh:mm a") if v else "—" }}{%- endmacro -%}
<style>
  @page { size: A4; margin: 15mm; }
  .lr { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; max-width: 180mm; margin: 0 auto; }
  .lr .letterhead-wrap { margin-bottom: 14px; }
  .lr .doc-bar { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 4px; }
  .lr .doc-title { font-size: 16px; font-weight: 700; }
  .lr .doc-meta { font-size: 11px; color: #555; text-align: right; }
  .lr .doc-ref { font-size: 11px; color: #555; margin-bottom: 16px; }
  .lr .prov { border: 2px solid #b91c1c; color: #b91c1c; text-align: center; font-weight: 700; font-size: 12px; padding: 6px; margin-bottom: 12px; letter-spacing: .08em; }
  .lr .section { margin-bottom: 14px; border: 1px solid #cfcfcf; border-radius: 4px; overflow: hidden; }
  .lr .section-head { font-size: 12px; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; padding: 6px 10px; border-bottom: 1px solid #1a1a1a; }
  .lr .field-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0; }
  .lr .field { padding: 7px 10px; border-top: 1px solid #ececec; font-size: 12px; display: flex; gap: 6px; }
  .lr .field:nth-of-type(-n+2) { border-top: none; }
  .lr .field dt { color: #666; flex: none; min-width: 42%; font-weight: 600; margin: 0; }
  .lr .field dd { margin: 0; }
  .lr table.res { width: 100%; border-collapse: collapse; font-size: 12px; }
  .lr table.res th, .lr table.res td { padding: 7px 10px; border-bottom: 1px solid #ececec; text-align: left; }
  .lr table.res th { background: #f3f3f3; border-bottom: 1px solid #cfcfcf; font-weight: 700; }
  .lr table.res tr:last-child td { border-bottom: none; }
  .lr .flag { font-weight: 700; }
  .lr .crit { color: #b91c1c; }
  .lr .f-normal { color: #15803d; }
  .lr .f-low { color: #1d4ed8; }
  .lr .f-high { color: #c2410c; }
  .lr .note { padding: 7px 10px; font-size: 12px; white-space: pre-line; border-top: 1px solid #ececec; }
  .lr .note:first-child { border-top: none; }
  .lr .doc-footer { margin-top: 26px; padding-top: 10px; border-top: 1px solid #000; }
  .lr .sig-row { display: flex; justify-content: space-between; gap: 40px; margin-bottom: 12px; }
  .lr .sig-line { flex: 1; text-align: center; font-size: 11px; color: #444; }
  .lr .sig-line .rule { border-top: 1px solid #888; margin-bottom: 4px; height: 30px; }
  .lr .sig-line b { color: #1a1a1a; }
  .lr .foot { font-size: 10.5px; color: #555; white-space: pre-line; margin-bottom: 6px; }
  .lr .foot-meta { display: flex; justify-content: space-between; font-size: 10px; color: #666; }
</style>
<div class="lr">
  <div class="letterhead-wrap">{{ (lh_content or "") | safe }}</div>

  <div class="doc-bar">
    <div class="doc-title">{{ _("Laboratory Report") }}</div>
    <div class="doc-meta">{{ _("Printed") }}: {{ frappe.utils.format_datetime(frappe.utils.now(), "dd MMM yyyy, hh:mm a") }}<br>{{ _("By") }}: {{ frappe.session.user }}</div>
  </div>
  <div class="doc-ref">{{ _("Report No") }}: {{ doc.name }} &middot; {{ _("Visit No") }}: {{ doc.patient_visit or "—" }} &middot; {{ _("UHIN") }}: {{ visit.uhin_id if visit and visit.uhin_id else "—" }}</div>

  {% if doc.status != "Reported" %}
  <div class="prov">PROVISIONAL &middot; NOT VERIFIED &middot; {{ doc.status | upper }}</div>
  {% endif %}

  <div class="section">
    <div class="section-head">{{ _("Patient Details") }}</div>
    <dl class="field-grid">
      <div class="field"><dt>{{ _("Patient Name") }}</dt><dd><b>{{ doc.patient_name or "—" }}</b></dd></div>
      <div class="field"><dt>{{ _("UHIN") }}</dt><dd>{{ visit.uhin_id if visit and visit.uhin_id else "—" }}</dd></div>
      <div class="field"><dt>{{ _("Age / Sex") }}</dt><dd>{{ age or "—" }} / {{ doc.sex or "—" }}</dd></div>
      <div class="field"><dt>{{ _("Referred By") }}</dt><dd>{{ doctor or "—" }}</dd></div>
    </dl>
  </div>

  <div class="section">
    <div class="section-head">{{ _("Test Details") }}</div>
    <dl class="field-grid">
      <div class="field"><dt>{{ _("Test") }}</dt><dd><b>{{ doc.item_name or doc.item or "—" }}</b></dd></div>
      <div class="field"><dt>{{ _("Department") }}</dt><dd>{{ dept or "—" }}</dd></div>
      <div class="field"><dt>{{ _("Sample ID") }}</dt><dd>{{ doc.lab_sample or "—" }}</dd></div>
      <div class="field"><dt>{{ _("Collected On") }}</dt><dd>{{ dt(doc.sample_collected_on) }}</dd></div>
      <div class="field"><dt>{{ _("Status") }}</dt><dd>{{ doc.status or "—" }}</dd></div>
      <div class="field"><dt>{{ _("Reported On") }}</dt><dd>{{ dt(doc.reported_on) }}</dd></div>
    </dl>
  </div>

  <div class="section">
    <div class="section-head">{{ _("Results") }}</div>
    {% if doc.results %}
    <table class="res">
      <thead><tr><th>{{ _("Parameter") }}</th><th>{{ _("Result") }}</th><th>{{ _("Unit") }}</th><th>{{ _("Normal Range") }}</th><th>{{ _("Flag") }}</th></tr></thead>
      <tbody>
        {% for r in doc.results %}
        <tr>
          <td>{{ r.parameter }}</td>
          <td>{% if r.flag and r.flag != 'Normal' %}<b>{{ r.result_value or "" }}</b>{% else %}{{ r.result_value or "" }}{% endif %}</td>
          <td>{{ r.unit or "" }}</td>
          <td>{{ r.normal_range or "" }}</td>
          <td class="flag {% if r.flag and r.flag.startswith('Critical') %}crit{% elif r.flag == 'Normal' %}f-normal{% elif r.flag == 'Low' %}f-low{% elif r.flag %}f-high{% endif %}">{{ r.flag or "" }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
    {% endif %}
    {% if doc.result %}<div class="note"><b>{{ _("Result") }}:</b> {{ doc.result }}</div>{% endif %}
    {% if doc.normal_range and not doc.results %}<div class="note"><b>{{ _("Normal Range") }}:</b> {{ doc.normal_range }}</div>{% endif %}
    {% if not doc.results and not doc.result %}<div class="note">{{ _("No results recorded.") }}</div>{% endif %}
  </div>

  {% if doc.critical_informed_to or doc.remarks %}
  <div class="section">
    <div class="section-head">{{ _("Remarks") }}</div>
    {% if doc.critical_informed_to %}<div class="note crit"><b>{{ _("Critical result informed") }}:</b> {{ _("to") }} {{ doc.critical_informed_to }}{% if doc.critical_informed_on %} {{ _("at") }} {{ dt(doc.critical_informed_on) }}{% endif %}{% if doc.critical_informed_by %} {{ _("by") }} {{ user_name(doc.critical_informed_by) }}{% endif %}</div>{% endif %}
    {% if doc.remarks %}<div class="note">{{ doc.remarks }}</div>{% endif %}
  </div>
  {% endif %}

  <div class="doc-footer">
    <div class="sig-row">
      <div class="sig-line"><div class="rule"></div>{{ _("Lab Technician") }}{% if doc.result_entered_by %}: <b>{{ user_name(doc.result_entered_by) }}</b>{% endif %}</div>
      <div class="sig-line"><div class="rule"></div>{{ signature_label or _("Verified by") }}{% if doc.verified_by %}: <b>{{ user_name(doc.verified_by) }}</b>{% endif %}</div>
    </div>
    {% if report_footer %}<div class="foot">{{ report_footer }}</div>{% endif %}
    <div class="foot-meta">
      <span>{{ _("Confidential patient record — for authorized hospital use only.") }}</span>
      <span>{{ _("Page 1 of 1") }}</span>
    </div>
  </div>
</div>
